#include <iomanip>
#include <iostream>
#include <limits>
int main() {
    static_assert(std::numeric_limits<double>::radix == 2);
    const double first = 0.625; // 1/2 + 1/8.
    const double second = 0.125; // 1/8.
    const double sum = first + second;
    std::cout << std::fixed << std::setprecision(3);
    std::cout << "first=" << first << '\n';
    std::cout << "sum=" << sum << '\n';
    std::cout << std::boolalpha << "exact three quarters="
              << (sum == 0.75) << '\n';
}

#include <cmath>
#include <iostream>
#include <limits>
bool accepted_measurement(double value) {
    return std::isfinite(value) && value >= 0.0;
}
int main() {
    static_assert(std::numeric_limits<double>::has_quiet_NaN);
    const double missing = std::numeric_limits<double>::quiet_NaN();
    std::cout << std::boolalpha;
    std::cout << "self equality=" << (missing == missing) << '\n';
    std::cout << "is NaN=" << std::isnan(missing) << '\n';
    std::cout << "measurement accepted=" << accepted_measurement(missing) << '\n';
    std::cout << "zero accepted=" << accepted_measurement(0.0) << '\n';
}

